    74  otError LeaderBase::GetContext(const Ip6::Address &aAddress, Lowpan::Context &aContext)
    75  {
    76      ThreadNetif &netif = GetNetif();
    77      PrefixTlv *  prefix;
    78      ContextTlv * contextTlv;
    79
    80      aContext.mPrefixLength = 0;
    81
    82      if (PrefixMatch(netif.GetMle().GetMeshLocalPrefix().m8, aAddress.mFields.m8, 64) >= 0)
    83      {
    84          aContext.mPrefix       = netif.GetMle().GetMeshLocalPrefix().m8;
    85          aContext.mPrefixLength = 64;
    86          aContext.mContextId    = 0;
    87          aContext.mCompressFlag = true;
    88      }
    89
    90      for (NetworkDataTlv *cur                                            = reinterpret_cast<NetworkDataTlv *>(mTlvs);
    91           cur < reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength); cur = cur->GetNext())
    92      {
    93          if (cur->GetType() != NetworkDataTlv::kTypePrefix)
    94          {
    95              continue;
    96          }
    97
    98          prefix = static_cast<PrefixTlv *>(cur);
    99
   100          if (PrefixMatch(prefix->GetPrefix(), aAddress.mFields.m8, prefix->GetPrefixLength()) < 0)
   101          {
   102              continue;
   103          }
   104
   105          contextTlv = FindContext(*prefix);
   106
   107          if (contextTlv == NULL)
   108          {
   109              continue;
   110          }
   111
   112          if (prefix->GetPrefixLength() > aContext.mPrefixLength)
   113          {
   114              aContext.mPrefix       = prefix->GetPrefix();
   115              aContext.mPrefixLength = prefix->GetPrefixLength();
   116              aContext.mContextId    = contextTlv->GetContextId();
   117              aContext.mCompressFlag = contextTlv->IsCompress();
   118          }
   119      }
